'use strict';

const ASSETS = {
  equip: "data:image/png;base64,",
  heirlooms: "data:image/png;base64,",
  blade: "data:image/png;base64,",
  proj: "data:image/png;base64,",
  grounds: "data:image/png;base64,",
  uicons: "data:image/png;base64,",
  avatars: "data:image/png;base64,",
  classicons: "data:image/png;base64,",
  units: "data:image/png;base64,",
  tiles: "data:image/png;base64,",
  icons: "data:image/png;base64,",
  skills: "data:image/png;base64,",
  fx: "data:image/png;base64,",
  stele: "data:image/png;base64,"
};

const IMG = {};
function loadAssets() {
  for (const k in ASSETS) {
    const im = new Image();
    im.src = ASSETS[k];
    IMG[k] = im;
  }
}
function imgReady(k) { return IMG[k] && IMG[k].complete && IMG[k].naturalWidth > 0; }

